import 'dart:convert';import 'package:http/http.dart' as http;import '../models/candle.dart';
class YahooProvider{Future<List<Candle>> fetch({required String symbol,String interval='5m',String range='5d'})async{final u=Uri.parse('https://query1.finance.yahoo.com/v8/finance/chart/${Uri.encodeComponent(symbol)}?range=$range&interval=$interval&includePrePost=true');final r=await http.get(u);if(r.statusCode!=200)throw Exception('Yahoo HTTP ${r.statusCode}');final j=jsonDecode(r.body);final x=j['chart']['result']?[0];if(x==null)throw Exception('Veri bulunamadı');final ts=(x['timestamp'] as List?)??[];final q=x['indicators']['quote'][0];final out=<Candle>[];for(var i=0;i<ts.length;i++){final o=q['open'][i],h=q['high'][i],l=q['low'][i],c=q['close'][i],v=q['volume'][i];if([o,h,l,c].every((z)=>z!=null))out.add(Candle(time:DateTime.fromMillisecondsSinceEpoch((ts[i] as num).toInt()*1000),open:(o as num).toDouble(),high:(h as num).toDouble(),low:(l as num).toDouble(),close:(c as num).toDouble(),volume:v==null?0:(v as num).toDouble()));}if(out.length<30)throw Exception('Yeterli mum yok');return out;}}
